// Fuzz stub for fast_float::integer_times_pow10 (all overloads)
// We call the non-template (double-return) overloads for signed and unsigned mantissa,
// and the template overloads for T=float and T=double.

// Generate mantissas and exponent
uint64_t um = *FUZZ_PARAM(uint64_t);
int64_t sm = (int64_t)(*FUZZ_PARAM(uint64_t)); // use full 64-bit domain
int exp = (int)( (int)(*FUZZ_PARAM(unsigned int) % 20001u) - 10000 ); // [-10000, 10000]

// 1) Non-template: unsigned mantissa -> double
{
    double r = fast_float::integer_times_pow10(um, exp);
    // The result should never be NaN per spec (only finite or +/-inf)
    FUZZ_ASSERT(r == r, "unsigned->double produced NaN");
    volatile double sink = r; (void)sink;
}

// 2) Non-template: signed mantissa -> double
{
    double r = fast_float::integer_times_pow10(sm, exp);
    FUZZ_ASSERT(r == r, "signed->double produced NaN");
    volatile double sink = r; (void)sink;
}

// 3) Template: unsigned mantissa -> float
{
    float r = fast_float::integer_times_pow10<float>(um, exp);
    FUZZ_ASSERT(r == r, "unsigned->float produced NaN");
    volatile float sink = r; (void)sink;
}

// 4) Template: signed mantissa -> float
{
    float r = fast_float::integer_times_pow10<float>(sm, exp);
    FUZZ_ASSERT(r == r, "signed->float produced NaN");
    volatile float sink = r; (void)sink;
}

// 5) Template: unsigned mantissa -> double
{
    double r = fast_float::integer_times_pow10<double>(um, exp);
    FUZZ_ASSERT(r == r, "unsigned->double(T) produced NaN");
    volatile double sink = r; (void)sink;
}

// 6) Template: signed mantissa -> double
{
    double r = fast_float::integer_times_pow10<double>(sm, exp);
    FUZZ_ASSERT(r == r, "signed->double(T) produced NaN");
    volatile double sink = r; (void)sink;
}

// Done. No persistent objects to output.

// Fuzz stub for fast_float::from_chars
// Exercise the template with T=float and T=double using UC=char.
// Generate a random byte string and select a valid subrange [first,last).

std::string s = FUZZ_PARAM_STR();
size_t size = s.size();
size_t i = size ? (*FUZZ_PARAM(unsigned int) % (unsigned int)size) : 0;
size_t j = size ? (i + (*FUZZ_PARAM(unsigned int) % (unsigned int)(size - i + 1))) : 0; // j in [i,size]
const char *first = s.data() + i;
const char *last  = s.data() + j;

// Select a format among fixed/scientific/general (avoid hex to stay within common configs)
unsigned int fmt_sel = *FUZZ_PARAM(unsigned int) % 3u;
fast_float::chars_format fmt = fast_float::chars_format::general;
if (fmt_sel == 0) {
    fmt = fast_float::chars_format::fixed;
} else if (fmt_sel == 1) {
    fmt = fast_float::chars_format::scientific;
} else {
    fmt = fast_float::chars_format::general;
}

// Parse as float
float fval = 0.0f;
auto rf = fast_float::from_chars<float, char>(first, last, fval, fmt);
// Returned ptr must lie within [first,last]
FUZZ_ASSERT(rf.ptr >= first && rf.ptr <= last, "from_chars<float>: ptr out of range");
// Only use fval on success per API (std::errc() indicates success)
if (rf.ec == std::errc()) {
    volatile float sinkf = fval; (void)sinkf;
}

// Parse as double
double dval = 0.0;
auto rd = fast_float::from_chars<double, char>(first, last, dval, fmt);
FUZZ_ASSERT(rd.ptr >= first && rd.ptr <= last, "from_chars<double>: ptr out of range");
if (rd.ec == std::errc()) {
    volatile double sinkd = dval; (void)sinkd;
}

// Validation: Ensures input range is valid, checks ptr bounds, and only consumes parsed values on success; no persistent objects to output.

// Fuzz stub for fast_float::from_chars_advanced
// Exercise with a floating-point (double) and an integer (int64_t) using UC=char.
// Generate a random byte string and select a valid subrange [first,last).

std::string s = FUZZ_PARAM_STR();
size_t size = s.size();
size_t i = size ? (*FUZZ_PARAM(unsigned int) % (unsigned int)size) : 0;
size_t j = size ? (i + (*FUZZ_PARAM(unsigned int) % (unsigned int)(size - i + 1))) : 0; // j in [i,size]
const char *first = s.data() + i;
const char *last  = s.data() + j;

// Construct default options; a default instance is valid per API.
fast_float::parse_options_t<char> opts{};

// Parse as double
double dval = 0.0;
auto rd = fast_float::from_chars_advanced<double, char>(first, last, dval, opts);
FUZZ_ASSERT(rd.ptr >= first && rd.ptr <= last, "from_chars_advanced<double>: ptr out of range");
if (rd.ec == std::errc()) {
    volatile double sinkd = dval; (void)sinkd;
}

// Parse as 64-bit signed integer
int64_t ival = 0;
auto ri = fast_float::from_chars_advanced<int64_t, char>(first, last, ival, opts);
FUZZ_ASSERT(ri.ptr >= first && ri.ptr <= last, "from_chars_advanced<int64_t>: ptr out of range");
if (ri.ec == std::errc()) {
    volatile int64_t sinki = ival; (void)sinki;
}

